-- Migration: 004_sales_tables.sql
-- Description: Sales tables: Quotation, Subscription, Lines, and Status History
-- Scope: D3 - Sales Tables (Brightloop SMS)

-- 1. Quotation table
-- Quotes generated by sales reps; can act as reusable templates (is_template = true).
CREATE TABLE IF NOT EXISTS quotation (
    quotation_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    number VARCHAR(50) NOT NULL UNIQUE,
    is_template BOOLEAN NOT NULL DEFAULT FALSE,
    customer_id BIGINT,
    plan_id BIGINT NOT NULL,
    validity_days INTEGER NOT NULL DEFAULT 30,
    status VARCHAR(20) NOT NULL DEFAULT 'draft',
    created_by BIGINT,
    notes TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_quotation_customer FOREIGN KEY (customer_id) REFERENCES customer(customer_id) ON DELETE RESTRICT,
    CONSTRAINT fk_quotation_plan FOREIGN KEY (plan_id) REFERENCES plan(plan_id) ON DELETE RESTRICT,
    CONSTRAINT fk_quotation_creator FOREIGN KEY (created_by) REFERENCES auth(id) ON DELETE SET NULL,
    CONSTRAINT chk_quotation_validity CHECK (validity_days > 0),
    CONSTRAINT chk_quotation_status CHECK (status IN ('draft', 'sent', 'accepted', 'expired', 'cancelled')),
    CONSTRAINT chk_quotation_template_customer CHECK (is_template = TRUE OR customer_id IS NOT NULL)
);

CREATE TRIGGER trg_quotation_updated_at
BEFORE UPDATE ON quotation
FOR EACH ROW EXECUTE FUNCTION fn_set_updated_at();

-- 2. Quotation Line table
CREATE TABLE IF NOT EXISTS quotation_line (
    line_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    quotation_id BIGINT NOT NULL,
    product_id BIGINT NOT NULL,
    variant_id BIGINT,
    quantity INTEGER NOT NULL DEFAULT 1,
    unit_price NUMERIC(12,2) NOT NULL DEFAULT 0.00,
    tax_id BIGINT,
    amount NUMERIC(12,2) NOT NULL DEFAULT 0.00,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_ql_quotation FOREIGN KEY (quotation_id) REFERENCES quotation(quotation_id) ON DELETE CASCADE,
    CONSTRAINT fk_ql_product FOREIGN KEY (product_id) REFERENCES product(product_id) ON DELETE RESTRICT,
    CONSTRAINT fk_ql_variant FOREIGN KEY (variant_id) REFERENCES product_variant(variant_id) ON DELETE RESTRICT,
    CONSTRAINT fk_ql_tax FOREIGN KEY (tax_id) REFERENCES tax(tax_id) ON DELETE RESTRICT,
    CONSTRAINT chk_ql_quantity CHECK (quantity > 0),
    CONSTRAINT chk_ql_unit_price CHECK (unit_price >= 0),
    CONSTRAINT chk_ql_amount CHECK (amount >= 0)
);

-- 3. Subscription table
-- The central recurring agreement record.
-- Number is auto-generated (e.g. SUB-2026-000123) if not explicitly provided.
CREATE TABLE IF NOT EXISTS subscription (
    subscription_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    number VARCHAR(50) NOT NULL UNIQUE,
    customer_id BIGINT NOT NULL,
    plan_id BIGINT NOT NULL,
    quotation_id BIGINT,
    start_date DATE NOT NULL DEFAULT CURRENT_DATE,
    expiry_date DATE,
    next_billing_date DATE NOT NULL,
    payment_terms VARCHAR(50) NOT NULL DEFAULT 'Immediate',
    status VARCHAR(20) NOT NULL DEFAULT 'draft',
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_subscription_customer FOREIGN KEY (customer_id) REFERENCES customer(customer_id) ON DELETE RESTRICT,
    CONSTRAINT fk_subscription_plan FOREIGN KEY (plan_id) REFERENCES plan(plan_id) ON DELETE RESTRICT,
    CONSTRAINT fk_subscription_quotation FOREIGN KEY (quotation_id) REFERENCES quotation(quotation_id) ON DELETE SET NULL,
    CONSTRAINT chk_subscription_dates CHECK (expiry_date IS NULL OR expiry_date >= start_date),
    CONSTRAINT chk_subscription_payment_terms CHECK (payment_terms IN ('Immediate', 'Net 15', 'Net 30')),
    CONSTRAINT chk_subscription_status CHECK (status IN ('draft', 'quotation', 'confirmed', 'active', 'paused', 'closed'))
);

CREATE TRIGGER trg_subscription_updated_at
BEFORE UPDATE ON subscription
FOR EACH ROW EXECUTE FUNCTION fn_set_updated_at();

-- 4. Subscription Line table
CREATE TABLE IF NOT EXISTS subscription_line (
    line_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    subscription_id BIGINT NOT NULL,
    product_id BIGINT NOT NULL,
    variant_id BIGINT,
    quantity INTEGER NOT NULL DEFAULT 1,
    unit_price NUMERIC(12,2) NOT NULL DEFAULT 0.00,
    tax_id BIGINT,
    amount NUMERIC(12,2) NOT NULL DEFAULT 0.00,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_sl_subscription FOREIGN KEY (subscription_id) REFERENCES subscription(subscription_id) ON DELETE CASCADE,
    CONSTRAINT fk_sl_product FOREIGN KEY (product_id) REFERENCES product(product_id) ON DELETE RESTRICT,
    CONSTRAINT fk_sl_variant FOREIGN KEY (variant_id) REFERENCES product_variant(variant_id) ON DELETE RESTRICT,
    CONSTRAINT fk_sl_tax FOREIGN KEY (tax_id) REFERENCES tax(tax_id) ON DELETE RESTRICT,
    CONSTRAINT chk_sl_quantity CHECK (quantity > 0),
    CONSTRAINT chk_sl_unit_price CHECK (unit_price >= 0),
    CONSTRAINT chk_sl_amount CHECK (amount >= 0)
);

-- 5. Subscription Status History table
-- Logs every transition across the subscription lifecycle with actor, timestamp, and reason.
CREATE TABLE IF NOT EXISTS subscription_status_history (
    history_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    subscription_id BIGINT NOT NULL,
    from_status VARCHAR(20),
    to_status VARCHAR(20) NOT NULL,
    changed_by BIGINT,
    reason TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_ssh_subscription FOREIGN KEY (subscription_id) REFERENCES subscription(subscription_id) ON DELETE CASCADE,
    CONSTRAINT fk_ssh_changed_by FOREIGN KEY (changed_by) REFERENCES auth(id) ON DELETE SET NULL,
    CONSTRAINT chk_ssh_to_status CHECK (to_status IN ('draft', 'quotation', 'confirmed', 'active', 'paused', 'closed'))
);

COMMENT ON TABLE quotation IS 'Sales quotes and quote templates.';
COMMENT ON TABLE subscription IS 'Active and historical customer subscription agreements.';
COMMENT ON TABLE subscription_line IS 'Subscribed product components and pricing breakdown.';
COMMENT ON TABLE subscription_status_history IS 'Audit trail of all lifecycle status transitions.';
